const formatReading = (value: number | null, unit: string) => {
  if (value === null) return 'Sem leitura';
  const decimals = unit === 'pH' ? 2 : unit === 'mV' ? 0 : value % 1 === 0 ? 0 : 2;
  const formatted = decimals === 0
    ? value.toFixed(0)
    : value.toFixed(decimals).replace(/(\.\d*?)0+$/, '$1').replace(/\.$/, '');
  return `${formatted} ${unit}`;
};

const cleanRuleText = (value: unknown) => {
  const text = String(value ?? '').replace(/\s+/g, ' ').trim();
  if (!text) return null;
  return text.charAt(0).toUpperCase() + text.slice(1);
};

type SensorAuditMetric = 'temperature' | 'ph' | 'oxygen' | 'redox' | 'salinity';
type SensorAuditRange = 'day' | 'week' | 'month';
type SensorAuditSort = 'newest' | 'oldest' | 'value_desc' | 'value_asc' | 'tank';

type SensorAuditRow = {
  id: string;
  timestamp: string;
  site: string;
  tank: string;
  status: string;
  alertId: string;
  metrics: Record<SensorAuditMetric, number | null>;
};

const SENSOR_AUDIT_CONFIG: Record<SensorAuditMetric, { label: string; unit: string; keys: string[] }> = {
  temperature: {
    label: 'Temperatura',
    unit: '°C',
    keys: ['temperature', 'temperatura', 'temp', 'water_temperature', 'water_temperature_c', 'temperature_c', 'temp_c', 'sensor_value', 'sensorValue', 'reading_value', 'readingValue', 'value']
  },
  ph: {
    label: 'pH',
    unit: 'pH',
    keys: ['ph', 'pH', 'sensor_value', 'sensorValue', 'reading_value', 'readingValue', 'value']
  },
  oxygen: {
    label: 'Oxigénio dissolvido',
    unit: 'mg/L',
    keys: ['oxygen', 'dissolved_oxygen', 'oxygen_mg_l', 'do_mg_l', 'o2', 'sensor_value', 'sensorValue', 'reading_value', 'readingValue', 'value']
  },
  redox: {
    label: 'Redox / ORP',
    unit: 'mV',
    keys: ['redox', 'orp', 'redox_mv', 'orp_mv', 'sensor_value', 'sensorValue', 'reading_value', 'readingValue', 'value']
  },
  salinity: {
    label: 'Salinidade',
    unit: 'PSU',
    keys: ['salinity', 'salinidade', 'salinidad', 'salt', 'psu', 'ppt', 'sensor_value', 'sensorValue', 'reading_value', 'readingValue', 'value']
  }
};

const sensorTypeMatchesMetric = (sensorType: string | null | undefined, metric: SensorAuditMetric) => {
  const normalized = String(sensorType ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[_-]+/g, ' ');
  if (!normalized) return false;
  return SENSOR_AUDIT_CONFIG[metric].keys.some((alias) => {
    const normalizedAlias = alias
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[_-]+/g, ' ');
    return normalized === normalizedAlias || normalized.includes(normalizedAlias);
  });
};

const sensorTypeFromUnit = (unit: string | null | undefined): SensorAuditMetric | null => {
  const normalized = String(unit ?? '').trim().toLowerCase();
  if (!normalized) return null;
  if (normalized === 'c' || normalized === '°c' || normalized.includes('celsius')) return 'temperature';
  if (normalized === 'ph') return 'ph';
  if (normalized.includes('mg/l') || normalized.includes('mg l')) return 'oxygen';
  if (normalized === 'mv' || normalized.includes('millivolt')) return 'redox';
  if (normalized === 'psu' || normalized === 'ppt') return 'salinity';
  return null;
};

const metricFromSensorType = (sensorType: string | null | undefined): SensorAuditMetric | null =>
  (Object.keys(SENSOR_AUDIT_CONFIG) as SensorAuditMetric[]).find((metric) =>
    sensorTypeMatchesMetric(sensorType, metric)
  ) ?? null;

const isoDateOnly = (value: Date) => {
  const year = value.getFullYear();
  const month = String(value.getMonth() + 1).padStart(2, '0');
  const day = String(value.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

const dayBounds = (dateText: string) => {
  const date = dateText ? new Date(`${dateText}T00:00:00`) : new Date();
  const start = Number.isNaN(date.getTime()) ? new Date() : date;
  start.setHours(0, 0, 0, 0);
  const end = new Date(start);
  end.setDate(end.getDate() + 1);
  return { start, end };
};

const rangeBounds = (range: SensorAuditRange, dateText: string) => {
  const { start, end } = dayBounds(dateText);
  if (range === 'day') return { start, end };
  const expandedStart = new Date(start);
  expandedStart.setDate(expandedStart.getDate() - (range === 'week' ? 6 : 29));
  return { start: expandedStart, end };
};

const buildSensorAuditRows = (_cases: ClinicalCase[], summary?: MvpDashboardSummary | null): SensorAuditRow[] => {
  const tableReadingRows = (summary?.sensorReadings ?? [])
    .map((reading): SensorAuditRow | null => {
      const metric = metricFromSensorType(reading.sensorType) ?? sensorTypeFromUnit(reading.unit);
      const value = normalizeSensorMetricValue(metric, reading.value ?? null);
      if (!metric || value === null || !reading.timestamp) return null;
      return {
        id: reading.id ?? `${metric}-${reading.timestamp}`,
        timestamp: reading.timestamp,
        site: reading.site ?? 'Instalação não indicada',
        tank: reading.tank ?? 'Tanque não indicado',
        status: 'Leitura registada',
        alertId: reading.id ?? 'leitura-ambiental',
        metrics: {
          temperature: metric === 'temperature' ? value : null,
          ph: metric === 'ph' ? value : null,
          oxygen: metric === 'oxygen' ? value : null,
          redox: metric === 'redox' ? value : null,
          salinity: metric === 'salinity' ? value : null
        }
      };
    })
    .filter((row): row is SensorAuditRow => Boolean(row));

  return tableReadingRows.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
};

const formatSensorAuditValue = (value: number | null, metric: SensorAuditMetric) => {
  if (value === null || value === undefined || Number.isNaN(value)) return '--';
  const unit = SENSOR_AUDIT_CONFIG[metric].unit;
  const decimals = metric === 'ph' ? 2 : metric === 'redox' ? 0 : 1;
  return `${value.toFixed(decimals)} ${unit}`;
};

const latestSummarySensorReading = (summary: MvpDashboardSummary | null | undefined, metric: SensorAuditMetric) => {
  const rows = (summary?.sensorReadings ?? [])
    .filter((row) => {
      const rowMetric = metricFromSensorType(row.sensorType) ?? sensorTypeFromUnit(row.unit);
      return rowMetric === metric &&
        normalizeSensorMetricValue(metric, row.value ?? null) !== null &&
        Boolean(row.timestamp);
    })
    .sort((a, b) => new Date(b.timestamp ?? 0).getTime() - new Date(a.timestamp ?? 0).getTime());
  return normalizeSensorMetricValue(metric, rows[0]?.value ?? null);
};

const latestMatchingSensorReading = (
  summary: MvpDashboardSummary | null | undefined,
  metric: SensorAuditMetric,
  sensorId?: string | null
) => {
  const expectedSensorId = String(sensorId ?? '').trim();
  const rows = (summary?.sensorReadings ?? [])
    .filter((row) => {
      const rowMetric = metricFromSensorType(row.sensorType) ?? sensorTypeFromUnit(row.unit);
      if (rowMetric !== metric || normalizeSensorMetricValue(metric, row.value ?? null) === null || !row.timestamp) return false;
      const sameSensor = expectedSensorId && String(row.sensorId ?? '').trim() === expectedSensorId;
      return sameSensor || rowMetric === metric;
    })
    .sort((a, b) => {
      const aSameSensor = expectedSensorId && String(a.sensorId ?? '').trim() === expectedSensorId;
      const bSameSensor = expectedSensorId && String(b.sensorId ?? '').trim() === expectedSensorId;
      if (aSameSensor !== bSameSensor) return bSameSensor ? 1 : -1;
      return new Date(b.timestamp ?? 0).getTime() - new Date(a.timestamp ?? 0).getTime();
    });
  return normalizeSensorMetricValue(metric, rows[0]?.value ?? null);
};

const mergeSensorReadings = (
  primary: MvpDashboardSummary['sensorReadings'],
  fallback: MvpDashboardSummary['sensorReadings']
): MvpDashboardSummary['sensorReadings'] => {
  const rows = [...(fallback ?? []), ...(primary ?? [])];
  if (!rows.length) return null;
  return Array.from(
    new Map(
      rows
        .sort((a, b) => new Date(b.timestamp ?? 0).getTime() - new Date(a.timestamp ?? 0).getTime())
        .map((row, index) => [row.id || `${row.sensorType ?? 'sensor'}-${row.timestamp ?? index}-${index}`, row])
    ).values()
  );
};

const sensorValueFromRows = (rows: MvpDashboardSummary['sensorReadings'], metric: SensorAuditMetric) => {
  const latest = (rows ?? [])
    .filter((row) => {
      const rowMetric = metricFromSensorType(row.sensorType) ?? sensorTypeFromUnit(row.unit);
      return rowMetric === metric &&
        normalizeSensorMetricValue(metric, row.value ?? null) !== null &&
        Boolean(row.timestamp);
    })
    .sort((a, b) => new Date(b.timestamp ?? 0).getTime() - new Date(a.timestamp ?? 0).getTime())[0];
  return normalizeSensorMetricValue(metric, latest?.value ?? null);
};

const latestSensorTimestamp = (rows: MvpDashboardSummary['sensorReadings']) =>
  (rows ?? [])
    .map((row) => row.timestamp)
    .filter((value): value is string => Boolean(value) && Number.isFinite(new Date(value).getTime()))
    .sort((a, b) => new Date(b).getTime() - new Date(a).getTime())[0] ?? null;

