import { useState } from 'react';
import { AlertTriangle, Home, RefreshCw } from 'lucide-react';
import { isRouteErrorResponse, useRouteError } from 'react-router-dom';
import { getErrorMessage, isDynamicImportFailure, resetBrowserStateAndReload } from '@/app/utils/browser-recovery';

export function RouteErrorBoundary() {
  const error = useRouteError();
  const [isRecovering, setIsRecovering] = useState(false);

  const message = isRouteErrorResponse(error) ? `${error.status} ${error.statusText}`.trim() : getErrorMessage(error);
  const moduleLoadFailure = isDynamicImportFailure(error);

  const handleRecovery = async () => {
    setIsRecovering(true);

    try {
      if (moduleLoadFailure) {
        await resetBrowserStateAndReload();
        return;
      }

      window.location.reload();
    } catch (recoveryError) {
      console.error('Failed to recover from route error:', recoveryError);
      window.location.reload();
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 px-4 py-10 text-white">
      <div className="mx-auto flex max-w-2xl flex-col items-center rounded-3xl border border-white/10 bg-white/5 p-8 text-center shadow-2xl backdrop-blur">
        <div className="mb-5 flex h-16 w-16 items-center justify-center rounded-2xl bg-orange-500/15 text-orange-300">
          <AlertTriangle className="h-8 w-8" />
        </div>

        <h1 className="text-2xl font-black tracking-tight">
          {moduleLoadFailure ? 'App failed to load the latest module' : 'Unexpected application error'}
        </h1>

        <p className="mt-3 max-w-xl text-sm leading-6 text-slate-300">
          {moduleLoadFailure
            ? 'This usually happens after a local code change when the browser still has stale cached files. Retry will clear cached app state and reload the page.'
            : 'The app hit an unexpected error while rendering this route. You can retry the page or return to the home screen.'}
        </p>

        <div className="mt-6 flex flex-wrap items-center justify-center gap-3">
          <button
            type="button"
            onClick={handleRecovery}
            disabled={isRecovering}
            className="inline-flex items-center gap-2 rounded-xl bg-orange-500 px-4 py-2.5 text-sm font-semibold text-white transition hover:bg-orange-400 disabled:cursor-not-allowed disabled:opacity-70"
          >
            <RefreshCw className={`h-4 w-4 ${isRecovering ? 'animate-spin' : ''}`} />
            {isRecovering ? 'Recovering...' : moduleLoadFailure ? 'Clear cache and reload' : 'Retry'}
          </button>

          <button
            type="button"
            onClick={() => window.location.assign('/')}
            className="inline-flex items-center gap-2 rounded-xl border border-white/15 bg-white/5 px-4 py-2.5 text-sm font-semibold text-white transition hover:bg-white/10"
          >
            <Home className="h-4 w-4" />
            Go home
          </button>
        </div>

        <div className="mt-6 w-full overflow-hidden rounded-2xl border border-white/10 bg-slate-900/80 text-left">
          <div className="border-b border-white/10 px-4 py-2 text-xs font-semibold uppercase tracking-[0.18em] text-slate-400">
            Error details
          </div>
          <pre className="overflow-x-auto px-4 py-4 text-xs leading-6 text-slate-300">{message}</pre>
        </div>
      </div>
    </div>
  );
}
