const slugify = (value: string) =>
  value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '');

const slugSegments = (value: unknown) =>
  String(value ?? '')
    .split(/[/?#]+/)
    .map((segment) => slugify(segment))
    .filter(Boolean);

const projectMatchesRoute = (row: any, routeProjectSlug: string, routeClientSlug: string) => {
  const rawSlug = String(row.slug ?? '');
  const slugParts = slugSegments(rawSlug);
  const directSlug = slugify(rawSlug);
  const nameSlug = slugify(String(row.name ?? ''));

  return (
    directSlug === routeProjectSlug ||
    directSlug === `${routeClientSlug}-${routeProjectSlug}` ||
    slugParts[slugParts.length - 1] === routeProjectSlug ||
    (slugParts[0] === routeClientSlug && slugParts[slugParts.length - 1] === routeProjectSlug) ||
    nameSlug === routeProjectSlug
  );
};

type ClientRouteStatus =
  | { state: 'checking' }
  | { state: 'found' }
  | { state: 'dead-end'; slug: string; segment: 'client' | 'project' | 'validation' };

const clientScopeFromRow = (row: any): ClientScope => ({
  id: String(row.client_id ?? ''),
  name: String(row.name ?? ''),
  slug: String(row.slug ?? ''),
  logo_url: row.logo_url ? String(row.logo_url) : undefined,
  primary_color: row.primary_color ? String(row.primary_color) : undefined,
  secondary_color: row.secondary_color ? String(row.secondary_color) : undefined,
  species_focus: row.species_focus ? String(row.species_focus) : undefined,
  default_phase: row.default_phase ? String(row.default_phase) as ClientScope['default_phase'] : undefined
});

