function ClientDashboardWrapper() {
  useAppIdentity('vision');
  const navigate = useNavigate();
  const params = useParams<{ clientSlug?: string; projectSlug?: string }>();
  const { setAvailableClients, setClient } = useGlobal();
  const [routeStatus, setRouteStatus] = React.useState<ClientRouteStatus>({ state: 'checking' });

  React.useEffect(() => {
    const rawClientSlug = params.clientSlug ?? '';
    const routeClientSlug = slugify(rawClientSlug);
    const routeProjectSlug = params.projectSlug ? slugify(params.projectSlug) : null;

    if (!routeClientSlug || !hasSupabaseConfig) {
      setClient(null);
      setAvailableClients([]);
      setRouteStatus({ state: 'dead-end', slug: rawClientSlug, segment: 'validation' });
      return;
    }

    let active = true;
    setRouteStatus({ state: 'checking' });

    const resolveClientRoute = async () => {
      try {
        const { data: routeRows, error: routeResolverError } = await supabase
          .rpc('aql_resolve_public_vision_route', {
            p_client_slug: routeClientSlug,
            p_project_slug: routeProjectSlug
          });

        const routeRow = Array.isArray(routeRows) ? routeRows[0] : routeRows;
        if (!routeResolverError && routeRow) {
          if (!routeRow.found) {
            setClient(null);
            setAvailableClients([]);
            setRouteStatus({
              state: 'dead-end',
              slug: routeProjectSlug ? `${rawClientSlug}/${params.projectSlug ?? ''}` : rawClientSlug,
              segment: routeRow.failure_segment === 'project' ? 'project' : 'client'
            });
            return;
          }

          const matchedClient = clientScopeFromRow(routeRow);
          setAvailableClients([matchedClient]);
          setClient(matchedClient);
          setRouteStatus({ state: 'found' });
          return;
        }

        const { data: clientRows, error: clientError } = await supabase
          .from('aql_clients')
          .select('client_id,name,slug,logo_url,primary_color,secondary_color')
          .eq('is_active', true)
          .order('name');

        if (clientError) throw clientError;

        const matchedClientRow = Array.isArray(clientRows)
          ? clientRows.find((row: any) =>
            slugify(String(row.slug ?? '')) === routeClientSlug ||
            slugify(String(row.name ?? '')) === routeClientSlug
          )
          : null;

        if (!active) return;

        if (!matchedClientRow) {
          setClient(null);
          setAvailableClients([]);
          setRouteStatus({ state: 'dead-end', slug: rawClientSlug, segment: 'client' });
          return;
        }

        if (routeProjectSlug) {
          const { data: projectRows, error: projectError } = await supabase
            .from('aql_projects')
            .select('project_id,name,slug')
            .eq('is_active', true)
            .eq('client_id', matchedClientRow.client_id);

          if (projectError) throw projectError;

          const matchedProject = Array.isArray(projectRows)
            ? projectRows.find((row: any) => projectMatchesRoute(row, routeProjectSlug, routeClientSlug))
            : null;

          if (!active) return;

          if (!matchedProject) {
            setClient(null);
            setAvailableClients([]);
            setRouteStatus({ state: 'dead-end', slug: `${rawClientSlug}/${params.projectSlug ?? ''}`, segment: 'project' });
            return;
          }
        }

        const matchedClient = clientScopeFromRow(matchedClientRow);
        setAvailableClients([matchedClient]);
        setClient(matchedClient);
        setRouteStatus({ state: 'found' });
      } catch (error) {
        console.error('Failed to validate AQL Vision route slug:', error);
        if (!active) return;
        setClient(null);
        setAvailableClients([]);
        setRouteStatus({ state: 'dead-end', slug: rawClientSlug, segment: 'validation' });
      }
    };

    resolveClientRoute();

    return () => {
      active = false;
    };
  }, [params.clientSlug, params.projectSlug, setAvailableClients, setClient]);

  if (routeStatus.state === 'checking') {
    return (
      <div className="flex min-h-screen items-center justify-center bg-[#061017] px-4 text-white">
        <AqlVisionLoader
          label="A validar endpoint AQL Vision..."
          detail="A confirmar o slug antes de abrir producao."
        />
      </div>
    );
  }

  if (routeStatus.state === 'dead-end') {
    return (
      <VisionDeadEnd
        slug={routeStatus.slug}
        segment={routeStatus.segment}
        onBack={() => navigate('/')}
      />
    );
  }

  return (
    <VisionAlerts
      apiUrl={aqlVisionApiUrl}
      publicAnonKey={publicAnonKey}
      onBack={() => navigate('/')}
    />
  );
}

function VisionClientCameraWrapper() {
  useAppIdentity('vision');
  const navigate = useNavigate();
  const params = useParams<{ clientSlug?: string; projectSlug?: string }>();
  const [searchParams] = useSearchParams();
  const { client } = useGlobal();
  const [resolvedClientId, setResolvedClientId] = React.useState<string | null>(client?.id ?? null);
  const [resolvedProjectId, setResolvedProjectId] = React.useState<string | null>(null);

  const dashboardPath = params.projectSlug
    ? `/${params.clientSlug ?? ''}/${params.projectSlug}`
    : `/${params.clientSlug ?? ''}`;
  const scopedClientId = params.projectSlug && !resolvedProjectId ? null : resolvedClientId;

  React.useEffect(() => {
    const routeClientSlug = params.clientSlug ? slugify(params.clientSlug) : null;
    const clientMatchesRoute = client && routeClientSlug
      ? slugify(client.slug) === routeClientSlug || slugify(client.name) === routeClientSlug
      : Boolean(client?.id);
    if (client?.id && clientMatchesRoute) {
      setResolvedClientId(client.id);
    } else if (params.clientSlug) {
      setResolvedClientId(null);
    }
    if (!params.clientSlug || !hasSupabaseConfig) {
      setResolvedProjectId(null);
      return;
    }
    let active = true;
    (async () => {
      try {
        const { data, error } = await supabase.rpc('aql_resolve_public_vision_route', {
          p_client_slug: params.clientSlug,
          p_project_slug: params.projectSlug ?? null
        });
        if (!active || error) return;
        const row = Array.isArray(data) ? data[0] : data;
        if (row?.client_id) setResolvedClientId(String(row.client_id));
        setResolvedProjectId(row?.project_id ? String(row.project_id) : null);
      } catch {
        // Silent fallback: VisionDemo will show the "no data" state.
        if (active) setResolvedProjectId(null);
      }
    })();
    return () => {
      active = false;
    };
  }, [client?.id, client?.name, client?.slug, params.clientSlug, params.projectSlug]);

  return (
    <VisionDemo
      onBack={() => navigate(dashboardPath)}
      onOpenAlerts={() => navigate(dashboardPath)}
      initialAlertId={searchParams.get('alertId')}
      demoMode={false}
      clientId={scopedClientId}
      projectId={resolvedProjectId}
    />
  );
}

