const createStandaloneRouter = window.location.protocol === "file:" ? createHashRouter : createBrowserRouter;

// Simplified standalone router
export const router = createStandaloneRouter([
  {
    path: "/",
    Component: StandaloneLayout,
    errorElement: <RouteErrorBoundary />,
    children: [
      {
        index: true,
        Component: NativeAwareEntryWrapper
      },
      {
        path: "mobile",
        Component: VisionMobileWrapper
      },
      {
        path: "mobile/demo",
        Component: VisionMobileDemoWrapper
      },
      {
        path: "admin",
        Component: ConfigurationAdminWrapper
      },
      {
        path: "growth",
        Component: VisionGrowthMonitorWrapper
      },
      {
        path: "demo",
        Component: DemoAccessLayout,
        children: [
          {
            index: true,
            Component: VisionDemoDashboardWrapper
          },
          {
            path: "alerts",
            Component: VisionDemoAlertsWrapper
          },
          {
            path: "camera",
            Component: VisionDemoWrapper
          }
        ]
      },
      {
        path: ":clientSlug/camera",
        Component: VisionClientCameraWrapper
      },
      {
        path: ":clientSlug/:projectSlug/camera",
        Component: VisionClientCameraWrapper
      },
      {
        path: ":clientSlug",
        Component: ClientDashboardWrapper
      },
      {
        path: ":clientSlug/:projectSlug",
        Component: ClientDashboardWrapper
      },
      {
        path: "*",
        element: <Navigate to="/" replace />
      }
    ]
  }
]);
