const AI_DISCLAIMER = 'Análise por IA · carece de revisão de patologista';

interface VisionAiAnalysis {
  description: string;
  suspectedFindings: string[];
  differentialHypotheses: string[];
  confidence: number | null;
  recommendedNextSteps: string;
  operationalAssessment?: string;
  analysisTags?: string[];
  validated?: boolean | null;
}

const formatAiAnalysisNotes = (analysis: VisionAiAnalysis): string => {
  const lines = [`[${AI_DISCLAIMER}]`, ''];
  if (analysis.description) {
    lines.push(analysis.description, '');
  }
  if (analysis.suspectedFindings.length) {
    lines.push(`Achados sugestivos: ${analysis.suspectedFindings.join('; ')}`);
  }
  if (analysis.differentialHypotheses.length) {
    lines.push(`Hipóteses (não diagnósticas): ${analysis.differentialHypotheses.join('; ')}`);
  }
  if (analysis.confidence !== null) {
    lines.push(`Confiança visual: ${Math.round(analysis.confidence * 100)}%`);
  }
  if (analysis.recommendedNextSteps) {
    lines.push('', `Próximos passos sugeridos: ${analysis.recommendedNextSteps}`);
  }
  lines.push('', 'A decisão clínica final é da responsabilidade do patologista.');
  return lines.join('\n').trim();
};

const normalizeAiAnalysis = (raw: any): VisionAiAnalysis | null => {
  if (!raw || typeof raw !== 'object') return null;
  const description = typeof raw.description === 'string' ? raw.description.trim() : '';
  const suspectedFindings = Array.isArray(raw.suspectedFindings) ? raw.suspectedFindings.map(String) : [];
  const differentialHypotheses = Array.isArray(raw.differentialHypotheses) ? raw.differentialHypotheses.map(String) : [];
  const confidence = typeof raw.confidence === 'number' ? raw.confidence : null;
  const recommendedNextSteps = typeof raw.recommendedNextSteps === 'string' ? raw.recommendedNextSteps.trim() : '';
  const operationalAssessment = typeof raw.operationalAssessment === 'string' ? raw.operationalAssessment.trim() : '';
  const analysisTags = Array.isArray(raw.analysisTags) ? raw.analysisTags.map(String) : [];
  const validated = typeof raw.validated === 'boolean' ? raw.validated : null;

  if (!description && !suspectedFindings.length && !differentialHypotheses.length && !recommendedNextSteps && !operationalAssessment && !analysisTags.length) {
    return null;
  }

  return {
    description,
    suspectedFindings,
    differentialHypotheses,
    confidence,
    recommendedNextSteps,
    operationalAssessment,
    analysisTags,
    validated
  };
};

type OverlayBox = { x: number; y: number; width: number; height: number; source: 'yolo' | 'gemini' };

const normalizeOverlayBox = (raw: any, source: OverlayBox['source'], imageSize?: { width: number; height: number } | null): OverlayBox | null => {
  if (!raw) return null;
  const arrayValue = Array.isArray(raw) ? raw : raw.bbox ?? raw.box ?? raw.boundingBox ?? raw.bounding_box ?? raw.bbox_2d;
  const value = Array.isArray(arrayValue)
    ? source === 'gemini' && arrayValue.length >= 4 && arrayValue.every((item) => Number.isFinite(Number(item))) && Math.max(...arrayValue.map(Number)) > 1
      ? {
        x: Number(arrayValue[1]),
        y: Number(arrayValue[0]),
        width: Number(arrayValue[3]) - Number(arrayValue[1]),
        height: Number(arrayValue[2]) - Number(arrayValue[0])
      }
      : { x: arrayValue[0], y: arrayValue[1], width: arrayValue[2], height: arrayValue[3] }
    : {
      x: raw.x ?? raw.left ?? raw.xmin ?? raw.x_min,
      y: raw.y ?? raw.top ?? raw.ymin ?? raw.y_min,
      width: raw.width ?? raw.w,
      height: raw.height ?? raw.h
    };
  let x = Number(value.x);
  let y = Number(value.y);
  let width = Number(value.width ?? ((raw.xmax ?? raw.x_max ?? raw.right) != null ? Number(raw.xmax ?? raw.x_max ?? raw.right) - x : undefined));
  let height = Number(value.height ?? ((raw.ymax ?? raw.y_max ?? raw.bottom) != null ? Number(raw.ymax ?? raw.y_max ?? raw.bottom) - y : undefined));
  if (![x, y, width, height].every(Number.isFinite) || width <= 0 || height <= 0) return null;
  const maxValue = Math.max(x, y, width, height, x + width, y + height);
  if (source === 'gemini' && maxValue > 1 && maxValue <= 1000) {
    x /= 1000;
    width /= 1000;
    y /= 1000;
    height /= 1000;
  } else if ((x > 1 || y > 1 || width > 1 || height > 1) && imageSize?.width && imageSize?.height) {
    x /= imageSize.width;
    width /= imageSize.width;
    y /= imageSize.height;
    height /= imageSize.height;
  }
  return {
    x: Math.max(0, Math.min(1, x)),
    y: Math.max(0, Math.min(1, y)),
    width: Math.max(0.01, Math.min(1, width)),
    height: Math.max(0.01, Math.min(1, height)),
    source
  };
};

