const sensorIconFor = (sensorType: string) => {
  const normalized = sensorType.toLowerCase();
  if (normalized.includes('temperature')) return Thermometer;
  if (normalized === 'ph' || normalized.includes('sensor_ph')) return FlaskConical;
  if (normalized.includes('dissolved_oxygen') || normalized.includes('oxygen')) return Droplets;
  if (normalized.includes('redox') || normalized.includes('orp')) return Zap;
  if (normalized.includes('water_level') || normalized === 'level') return Gauge;
  if (normalized.includes('salinity')) return Waves;
  return Cog6ToothIcon;
};

const ruleSensorId = (rule: Record<string, any>) =>
  String(rule.sensor_id ?? rule.value?.sensor_id ?? rule.value?.sensorId ?? rule.value?.source_sensor_id ?? '').trim();

const toEntityId = (value: unknown) => String(value ?? '').trim();

const sensorBelongsToKit = (sensor: AqlSensor, kit: AqlKit, kitDeviceIds = new Set<string>()) => {
  const sensorKitId = toEntityId(sensor.kit_id);
  const sensorZoneId = toEntityId(sensor.zone_id);
  const sensorDeviceId = toEntityId((sensor as Record<string, any>).device_id);

  return (
    sensorKitId === kit.kit_id ||
    sensorDeviceId === kit.kit_id ||
    (sensorDeviceId ? kitDeviceIds.has(sensorDeviceId) : false) ||
    Boolean(!sensorKitId && sensorZoneId && sensorZoneId === toEntityId(kit.zone_id))
  );
};

const sensorBelongsToProject = (
  sensor: AqlSensor,
  projectKitIds: Set<string>,
  projectZoneIds: Set<string>,
  projectDeviceIds: Set<string>
) => {
  const sensorKitId = toEntityId(sensor.kit_id);
  const sensorZoneId = toEntityId(sensor.zone_id);
  const sensorDeviceId = toEntityId((sensor as Record<string, any>).device_id);

  return (
    projectKitIds.has(sensorKitId) ||
    projectKitIds.has(sensorDeviceId) ||
    projectDeviceIds.has(sensorDeviceId) ||
    (sensorZoneId ? projectZoneIds.has(sensorZoneId) : false)
  );
};

const readStoredPositions = (storageKey: string) => {
  if (typeof window === 'undefined') return new Map<string, { x: number; y: number }>();
  try {
    const parsed = JSON.parse(window.localStorage.getItem(storageKey) ?? '{}') as Record<string, { x: number; y: number }>;
    return new Map(
      Object.entries(parsed)
        .filter(([, position]) => Number.isFinite(position?.x) && Number.isFinite(position?.y))
        .map(([id, position]) => [id, position])
    );
  } catch {
    return new Map<string, { x: number; y: number }>();
  }
};

const writeStoredPositions = (storageKey: string, nodes: Node<ArchitectureGraphNodeData>[]) => {
  if (typeof window === 'undefined') return;
  const payload = nodes.reduce<Record<string, { x: number; y: number }>>((acc, node) => {
    acc[node.id] = node.position;
    return acc;
  }, {});
  window.localStorage.setItem(storageKey, JSON.stringify(payload));
};

