const makeEdge = (source: string, target: string, relation: ArchitectureRelation): Edge => ({
  id: `${source}->${target}:${relation}`,
  source,
  target,
  type: 'smoothstep',
  deletable: true,
  style: {
    stroke: '#94a3b8',
    strokeOpacity: 0.72,
    strokeWidth: 1.5
  },
  data: { relation }
});

const centerForNode = (node: Node<ArchitectureGraphNodeData>) => {
  const w = NODE_WIDTH;
  const h = NODE_HEIGHT;
  return { x: node.position.x + w / 2, y: node.position.y + h / 2 };
};

const bestHandlesForNodes = (sourceNode: Node<ArchitectureGraphNodeData>, targetNode: Node<ArchitectureGraphNodeData>) => {
  const sourceCenter = centerForNode(sourceNode);
  const targetCenter = centerForNode(targetNode);
  const dx = targetCenter.x - sourceCenter.x;
  const dy = targetCenter.y - sourceCenter.y;

  if (Math.abs(dx) >= Math.abs(dy)) {
    return dx >= 0
      ? { sourceHandle: 'source-right', targetHandle: 'target-left' }
      : { sourceHandle: 'source-left', targetHandle: 'target-right' };
  }

  return dy >= 0
    ? { sourceHandle: 'source-bottom', targetHandle: 'target-top' }
    : { sourceHandle: 'source-top', targetHandle: 'target-bottom' };
};

const applyEdgeHandles = (nodes: Node<ArchitectureGraphNodeData>[], edges: Edge[]) => {
  const nodeMap = new Map(nodes.map((node) => [node.id, node]));
  const siblingGroupCounts = edges.reduce<Record<string, number>>((acc, edge) => {
    const targetNode = nodeMap.get(edge.target);
    if (!targetNode) return acc;
    const key = `${edge.source}:${targetNode.data.type}`;
    acc[key] = (acc[key] ?? 0) + 1;
    return acc;
  }, {});

  return edges.map((edge) => {
    const sourceNode = nodeMap.get(edge.source);
    const targetNode = nodeMap.get(edge.target);
    if (!sourceNode || !targetNode) return edge;
    const siblingKey = `${edge.source}:${targetNode.data.type}`;
    if ((siblingGroupCounts[siblingKey] ?? 0) > 1) {
      return {
        ...edge,
        sourceHandle: 'source-bottom',
        targetHandle: 'target-top'
      };
    }
    return {
      ...edge,
      ...bestHandlesForNodes(sourceNode, targetNode)
    };
  });
};

const buildGraph = (
  clients: AqlClient[],
  dataset: AqlConfigurationDataset,
  projects: AqlProject[],
  rules: Array<Record<string, any>>,
  storedPositions: Map<string, { x: number; y: number }>
) => {
  const nodes: Node<ArchitectureGraphNodeData>[] = [];
  const edges: Edge[] = [];
  const positionFor = (id: string, fallback: { x: number; y: number }) => storedPositions.get(id) ?? fallback;

  if (!clients.length) return { nodes, edges };

  let globalYCursor = 0;

  clients.forEach((client) => {
    const clientNodeId = `client:${client.client_id}`;
    const clientProjects = projects.filter((project) => project.client_id === client.client_id);

    nodes.push(makeNode(clientNodeId, 'client', positionFor(clientNodeId, { x: LEVEL_X.client, y: globalYCursor }), {
      title: client.name,
      subtitle: client.slug ? `/${client.slug}` : 'Código por definir',
      meta: client.is_active ? 'Ativo' : 'Inativo',
        value: client
      }));

    let clientYCursor = globalYCursor;

    clientProjects.forEach((project) => {
      const projectNodeId = `project:${project.project_id}`;
      const projectY = clientYCursor;
      const projectLocations = dataset.locations.filter((location) =>
        location.client_id === client.client_id &&
        (!location.project_id || location.project_id === project.project_id)
      );
      const projectLocationIds = new Set(projectLocations.map((item) => item.location_id));
      const projectZones = dataset.zones.filter((zone) =>
        zone.client_id === client.client_id &&
        (zone.project_id === project.project_id || projectLocationIds.has(zone.location_id))
      );
      const projectZoneIds = new Set(projectZones.map((item) => item.zone_id));
      const projectKits = dataset.kits.filter((kit) =>
        kit.client_id === client.client_id &&
        (
          kit.project_id === project.project_id ||
          projectLocationIds.has(kit.location_id) ||
          (kit.zone_id ? projectZoneIds.has(kit.zone_id) : false)
        )
      );
      const projectKitIds = new Set(projectKits.map((item) => item.kit_id));
      const projectCameras = dataset.cameras.filter((camera) =>
        camera.client_id === client.client_id &&
        (
          (camera.kit_id ? projectKitIds.has(camera.kit_id) : false) ||
          (camera.zone_id ? projectZoneIds.has(camera.zone_id) : false)
        )
      );
      const projectUltrasound = dataset.ultrasoundDevices.filter((device) =>
        device.client_id === client.client_id &&
        projectKitIds.has(device.kit_id)
      );
      const projectDeviceIds = new Set(projectUltrasound.map((device) => device.device_id));
      const projectSensors = dataset.sensors.filter((sensor) =>
        sensorBelongsToProject(sensor, projectKitIds, projectZoneIds, projectDeviceIds)
      );
      const projectRules = rules.filter((rule) => rule.project_id === project.project_id || rule.client_id === project.client_id);
      const placedRuleIds = new Set<string>();

      nodes.push(makeNode(projectNodeId, 'project', positionFor(projectNodeId, { x: LEVEL_X.project, y: projectY }), {
        title: project.name,
        subtitle: [project.species_focus, project.default_phase].filter(Boolean).join(' · ') || 'Espécie/fase por definir',
        meta: `${formatCount(projectLocations.length, 'instalação', 'instalações')} · ${formatCount(projectKits.length, 'unidade', 'unidades')}`,
        value: project
      }));
      edges.push(makeEdge(clientNodeId, projectNodeId, 'owns'));

    projectLocations.forEach((location, locationIndex) => {
      const locationNodeId = `location:${location.location_id}`;
      const locationY = projectY + locationIndex * 280;
      nodes.push(makeNode(locationNodeId, 'location', positionFor(locationNodeId, { x: LEVEL_X.location, y: locationY }), {
        title: location.name,
        subtitle: [location.city, location.country].filter(Boolean).join(', ') || location.type || 'Localização por definir',
        meta: location.latitude != null && location.longitude != null ? 'Georreferenciada' : 'Sem coordenadas',
        value: location
      }));
      edges.push(makeEdge(projectNodeId, locationNodeId, 'contains'));

      const locationZones = projectZones.filter((zone) => zone.location_id === location.location_id);
      locationZones.forEach((zone, zoneIndex) => {
        const zoneNodeId = `zone:${zone.zone_id}`;
        const zoneY = locationY + zoneIndex * 180;

        nodes.push(makeNode(zoneNodeId, 'zone', positionFor(zoneNodeId, { x: LEVEL_X.zone, y: zoneY }), {
          title: zone.name,
          subtitle: [zone.species, zone.phase].filter(Boolean).join(' · ') || zone.type || 'Área por caracterizar',
          meta: zone.code ? `Código ${zone.code}` : 'Sem código operacional',
          value: zone
        }));
        edges.push(makeEdge(locationNodeId, zoneNodeId, 'contains'));

        const zoneKits = projectKits.filter((kit) => kit.zone_id === zone.zone_id);
        zoneKits.forEach((kit, kitIndex) => {
          const kitNodeId = `kit:${kit.kit_id}`;
          const kitY = zoneY + kitIndex * 180;
          nodes.push(makeNode(kitNodeId, 'kit', positionFor(kitNodeId, { x: LEVEL_X.kit, y: kitY }), {
            title: kit.name,
            subtitle: kit.kit_type || 'Tipo por definir',
            meta: kit.device_uid || kit.serial_number || 'Identificador por definir',
            value: kit
          }));
          edges.push(makeEdge(zoneNodeId, kitNodeId, 'monitors'));

          const kitDevices: Array<{
            id: string;
            type: ArchitectureNodeType;
            y: number;
            title: string;
            subtitle: string;
            meta?: string;
            value: Record<string, any>;
          }> = [
            ...projectCameras.filter((camera) => camera.kit_id === kit.kit_id).map((camera) => ({
              id: `camera:${camera.camera_id}`,
              type: 'camera' as const,
              y: 0,
              title: camera.name || camera.camera_code || 'Câmara sem nome',
              subtitle: camera.live_feed_path || camera.source_type || 'Feed por definir',
              meta: camera.camera_code || 'Código por definir',
              value: camera
            })),
            ...projectSensors.filter((sensor) => {
              const kitDeviceIds = new Set(projectUltrasound
                .filter((device) => device.kit_id === kit.kit_id)
                .map((device) => device.device_id));
              return sensorBelongsToKit(sensor, kit, kitDeviceIds);
            }).map((sensor) => {
              const normalizedType = String(sensor.sensor_type ?? '').toLowerCase();
              return {
                id: `sensor:${sensor.sensor_id}`,
                type: 'sensor' as const,
                y: 0,
                title: sensor.name || sensorLabelMap[normalizedType] || 'Sensor',
                subtitle: sensorLabelMap[normalizedType] || sensor.sensor_type || 'Sensor',
                meta: sensor.unit ? `Unidade ${sensor.unit}` : 'Unidade por definir',
                value: sensor
              };
            }),
            ...projectUltrasound.filter((device) => device.kit_id === kit.kit_id).map((device) => ({
              id: `ultrasound:${device.device_id}`,
              type: 'ultrasound' as const,
              y: 0,
              title: device.name,
              subtitle: device.description || 'Sonda associada à unidade',
              meta: device.device_uid || 'Identificador por definir',
              value: device
            }))
          ];

          kitDevices.forEach((device, deviceIndex) => {
            const relation: ArchitectureRelation =
              device.type === 'camera' ? 'camera_feed' :
              device.type === 'sensor' ? 'sensor_feed' :
              'probe_feed';
            nodes.push(makeNode(device.id, device.type, positionFor(device.id, { x: LEVEL_X.device, y: kitY + deviceIndex * 130 }), {
              title: device.title,
              subtitle: device.subtitle,
              meta: device.meta,
              value: device.value
            }));
            edges.push(makeEdge(kitNodeId, device.id, relation));

            if (device.type === 'sensor') {
              const sensorRules = projectRules.filter((rule) => ruleSensorId(rule) === device.value.sensor_id);
              sensorRules.forEach((rule, ruleIndex) => {
                const ruleNodeId = `threshold:${rule.setting_id}`;
                placedRuleIds.add(rule.setting_id);
                nodes.push(makeNode(ruleNodeId, 'threshold', positionFor(ruleNodeId, { x: LEVEL_X.rule, y: kitY + deviceIndex * 130 + ruleIndex * 130 }), {
                  title: rule.key || 'Regra sem chave',
                  subtitle: device.title,
                  meta: 'Aplicada ao sensor',
                  value: rule
                }));
                edges.push(makeEdge(device.id, ruleNodeId, 'alert_rule'));
              });
            }
          });
        });
      });
    });

    projectRules.filter((rule) => !placedRuleIds.has(rule.setting_id)).forEach((rule, ruleIndex) => {
      const sensorId = ruleSensorId(rule);
      const ruleNodeId = `threshold:${rule.setting_id}`;
      nodes.push(makeNode(ruleNodeId, 'threshold', positionFor(ruleNodeId, { x: LEVEL_X.rule, y: projectY + 520 + ruleIndex * 130 }), {
        title: rule.key || 'Regra sem chave',
        subtitle: sensorId ? 'Sensor não encontrado' : 'Sensor por associar',
        meta: 'Requer associação a um sensor',
        value: rule
      }));
      edges.push(makeEdge(projectNodeId, ruleNodeId, 'alert_rule'));
    });

      clientYCursor += Math.max(360, projectLocations.length * 300, projectKits.length * 180);
    });

    globalYCursor = clientYCursor + 260;
  });

  return { nodes, edges: applyEdgeHandles(nodes, edges) };
};

const relationForConnection = (sourceType: ArchitectureNodeType, targetType: ArchitectureNodeType): ArchitectureRelation | null => {
  if (sourceType === 'client' && targetType === 'project') return 'owns';
  if (sourceType === 'project' && targetType === 'location') return 'contains';
  if (sourceType === 'location' && targetType === 'zone') return 'contains';
  if (sourceType === 'zone' && targetType === 'kit') return 'monitors';
  if (sourceType === 'kit' && targetType === 'camera') return 'camera_feed';
  if (sourceType === 'kit' && targetType === 'sensor') return 'sensor_feed';
  if (sourceType === 'kit' && targetType === 'ultrasound') return 'probe_feed';
  if (sourceType === 'sensor' && targetType === 'threshold') return 'alert_rule';
  return null;
};

const handleClassName = '!h-3 !w-3 !border-2 !border-white !bg-sky-500 !shadow-sm';

function ArchitectureCardNode({ data, selected }: NodeProps<Node<ArchitectureGraphNodeData>>) {
  const Icon = data.type === 'sensor'
    ? sensorIconFor(String(data.value?.sensor_type ?? ''))
    : nodeIconMap[data.type];

  return (
    <div
      className={`relative w-[300px] rounded-xl border p-3 pr-4 text-left shadow-[0_18px_44px_-32px_rgba(15,23,42,0.8)] transition-shadow overflow-hidden ${nodeToneClass[data.type]} ${selected ? 'ring-2 ring-primary/45' : ''}`}
    >
      <Handle id="target-left" type="target" position={Position.Left} className={handleClassName} />
      <Handle id="source-left" type="source" position={Position.Left} className={handleClassName} />
      <Handle id="target-right" type="target" position={Position.Right} className={handleClassName} />
      <Handle id="source-right" type="source" position={Position.Right} className={handleClassName} />
      <Handle id="target-top" type="target" position={Position.Top} className={handleClassName} />
      <Handle id="source-top" type="source" position={Position.Top} className={handleClassName} />
      <Handle id="target-bottom" type="target" position={Position.Bottom} className={handleClassName} />
      <Handle id="source-bottom" type="source" position={Position.Bottom} className={handleClassName} />
      <div className="flex items-start justify-between gap-2">
        <div className="flex min-w-0 items-start gap-2.5">
          <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg border border-current/15 bg-white/55 text-current shadow-sm dark:bg-white/10 dark:shadow-black/20">
            <Icon className="h-4 w-4" />
          </span>
          <span className="min-w-0">
            <span className="block text-[9px] font-bold uppercase tracking-[0.16em] text-current/55">{nodeTypeLabel[data.type]}</span>
            <span className="mt-0.5 block truncate text-sm font-bold text-current">{data.title}</span>
            {data.subtitle ? <span className="mt-0.5 block truncate text-xs font-medium text-current/62">{data.subtitle}</span> : null}
          </span>
        </div>
      </div>
      {data.meta ? (
        <div className="mt-3 border-t border-current/10 pt-2 text-[11px] font-semibold leading-4 text-current/62">
          {data.meta}
        </div>
      ) : null}
    </div>
  );
}

const nodeTypes = {
  architectureCard: ArchitectureCardNode
};

export function OperationalArchitectureFlow({ client, clients, allowClientCreation = false, discardDraftNodeId = null, dataset, projects, rules, onOpenNode }: OperationalArchitectureFlowProps) {
  const graphClients = useMemo(() => clients?.length ? clients : client ? [client] : [], [client, clients]);
  const visiblePaletteNodeTypes = useMemo(
    () => paletteNodeTypes.filter((item) => allowClientCreation || item.type !== 'client'),
    [allowClientCreation]
  );
  const storageKey = storageKeyForClient(graphClients.length === 1 ? graphClients[0]?.client_id ?? null : null);
  const [flowInstance, setFlowInstance] = useState<ReactFlowInstance<ArchitectureGraphNodeData> | null>(null);
  const initialGraph = useMemo(
    () => buildGraph(graphClients, dataset, projects, rules, readStoredPositions(storageKey)),
    [graphClients, dataset, projects, rules, storageKey]
  );
  const [nodes, setNodes] = useNodesState<ArchitectureGraphNodeData>(initialGraph.nodes);
  const [edges, setEdges, onEdgesChangeBase] = useEdgesState(initialGraph.edges);
  const [selectedEdgeId, setSelectedEdgeId] = useState<string | null>(null);
  const [toolbarHidden, setToolbarHidden] = useState(false);
  const previousGraphNodeIdsRef = useRef<Set<string>>(new Set(initialGraph.nodes.map((node) => node.id)));

  useEffect(() => {
    const previousGraphNodeIds = previousGraphNodeIdsRef.current;
    const hasNewGraphNodes = initialGraph.nodes.some((node) => !previousGraphNodeIds.has(node.id));
    previousGraphNodeIdsRef.current = new Set(initialGraph.nodes.map((node) => node.id));

    setNodes((currentNodes) => {
      const currentPositionMap = new Map(currentNodes.map((node) => [node.id, node.position]));
      const nextNodes = initialGraph.nodes.map((node) => ({
        ...node,
        position: currentPositionMap.get(node.id) ?? node.position
      }));
      setEdges(applyEdgeHandles(nextNodes, initialGraph.edges));
      return nextNodes;
    });

    if (hasNewGraphNodes && flowInstance) {
      requestAnimationFrame(() => {
        flowInstance.fitView({ padding: 0.12, duration: 420, minZoom: READABLE_MIN_ZOOM, maxZoom: 0.86 });
      });
    }
  }, [flowInstance, initialGraph, setEdges, setNodes]);

  useEffect(() => {
    writeStoredPositions(storageKey, nodes);
  }, [nodes, storageKey]);

  useEffect(() => {
    if (!discardDraftNodeId) return;
    setNodes((currentNodes) => currentNodes.filter((node) => node.id !== discardDraftNodeId));
  }, [discardDraftNodeId, setNodes]);

  const onNodesChange = useCallback((changes: NodeChange[]) => {
    setNodes((currentNodes) => {
      const nextNodes = applyNodeChanges(changes, currentNodes) as Node<ArchitectureGraphNodeData>[];
      setEdges((currentEdges) => applyEdgeHandles(nextNodes, currentEdges));
      return nextNodes;
    });
  }, [setEdges, setNodes]);

  const onEdgesChange = useCallback((changes: EdgeChange[]) => {
    onEdgesChangeBase(changes);
  }, [onEdgesChangeBase]);

  const onConnect = useCallback((connection: Connection) => {
    if (!connection.source || !connection.target || connection.source === connection.target) return;
    const sourceNode = nodes.find((node) => node.id === connection.source);
    const targetNode = nodes.find((node) => node.id === connection.target);
    if (!sourceNode || !targetNode) return;

    const relation = relationForConnection(sourceNode.data.type, targetNode.data.type);
    if (!relation) return;

    setEdges((currentEdges) => {
      const nextEdge = applyEdgeHandles(nodes, [makeEdge(connection.source!, connection.target!, relation)])[0];
      if (currentEdges.some((edge) => edge.id === nextEdge.id)) return currentEdges;
      return addEdge(nextEdge, currentEdges);
    });
  }, [nodes, setEdges]);

  const removeSelectedEdge = () => {
    if (!selectedEdgeId) return;
    setEdges((currentEdges) => currentEdges.filter((edge) => edge.id !== selectedEdgeId));
    setSelectedEdgeId(null);
  };
  const fitReadableView = useCallback(() => {
    flowInstance?.fitView({ padding: 0.12, duration: 420, minZoom: READABLE_MIN_ZOOM, maxZoom: 0.86 });
  }, [flowInstance]);
  const hideToolbar = useCallback(() => setToolbarHidden(true), []);
  const showToolbar = useCallback(() => setToolbarHidden(false), []);

  const handlePaletteDragStart = (event: DragEvent<HTMLButtonElement>, nodeType: ArchitectureNodeType) => {
    event.dataTransfer.setData('application/aql-node-type', nodeType);
    event.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = useCallback((event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = 'move';
  }, []);

  const handleDrop = useCallback((event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    const nodeType = event.dataTransfer.getData('application/aql-node-type') as ArchitectureNodeType;
    if (!nodeType || !visiblePaletteNodeTypes.some((item) => item.type === nodeType) || !flowInstance) return;

    const position = flowInstance.screenToFlowPosition({
      x: event.clientX,
      y: event.clientY
    });
    const draftNode = makeDraftNode(nodeType, position);
    setNodes((currentNodes) => [...currentNodes, draftNode]);
    onOpenNode(nodeType, draftNode.data.value, { draftNodeId: draftNode.id });
  }, [flowInstance, onOpenNode, setNodes, visiblePaletteNodeTypes]);

  return (
    <div className="aql-operational-flow h-[calc(100dvh-6.5rem)] min-h-[620px] overflow-hidden rounded-2xl border border-border bg-card dark:bg-slate-950/70">
      <style>
        {`
          .aql-operational-flow .react-flow__pane {
            cursor: grab;
          }

          .aql-operational-flow .react-flow__pane:active {
            cursor: grabbing;
          }

          .aql-operational-flow .react-flow__controls {
            overflow: hidden;
            border: 1px solid hsl(var(--border));
            border-radius: 12px;
            box-shadow: 0 18px 40px -28px rgba(2, 6, 23, 0.65);
          }

          .aql-operational-flow .react-flow__controls-button {
            width: 34px;
            height: 34px;
            border-bottom: 1px solid hsl(var(--border));
            background: hsl(var(--card) / 0.94);
            color: hsl(var(--foreground));
          }

          .aql-operational-flow .react-flow__controls-button:hover {
            background: hsl(var(--muted));
          }

          .aql-operational-flow .react-flow__minimap {
            overflow: hidden;
            border: 1px solid hsl(var(--border));
            border-radius: 12px;
            background: hsl(var(--card) / 0.92);
            box-shadow: 0 18px 40px -28px rgba(2, 6, 23, 0.65);
          }

          .dark .aql-operational-flow .react-flow__controls,
          .dark .aql-operational-flow .react-flow__minimap {
            border-color: rgba(148, 163, 184, 0.28);
            box-shadow: 0 18px 54px -30px rgba(0, 0, 0, 0.85);
          }

          .dark .aql-operational-flow .react-flow__controls-button {
            border-bottom-color: rgba(148, 163, 184, 0.22);
            background: rgba(15, 23, 42, 0.92);
            color: rgb(226, 232, 240);
          }

          .dark .aql-operational-flow .react-flow__controls-button:hover {
            background: rgba(30, 41, 59, 0.96);
          }

          .aql-operational-flow .react-flow__selection {
            border: 1px solid rgb(14, 165, 233);
            background: rgba(14, 165, 233, 0.12);
          }

          .dark .aql-operational-flow .react-flow__selection {
            border-color: rgb(56, 189, 248);
            background: rgba(56, 189, 248, 0.16);
          }
        `}
      </style>
      <ReactFlow
        nodes={nodes}
        edges={edges}
        nodeTypes={nodeTypes}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        onConnect={onConnect}
        onInit={setFlowInstance}
        onDragOver={handleDragOver}
        onDrop={handleDrop}
        onMoveStart={hideToolbar}
        onMoveEnd={showToolbar}
        onNodeDragStart={hideToolbar}
        onNodeDragStop={showToolbar}
        onSelectionDragStart={hideToolbar}
        onSelectionDragStop={showToolbar}
        onNodeClick={(event, node) => {
          if (event.shiftKey || event.metaKey || event.ctrlKey) return;
          onOpenNode(node.data.type, node.data.value);
        }}
        onNodeDoubleClick={(event, node) => {
          if (event.shiftKey || event.metaKey || event.ctrlKey) return;
          onOpenNode(node.data.type, node.data.value);
        }}
        onEdgeClick={(_, edge) => setSelectedEdgeId(edge.id)}
        defaultViewport={READABLE_INITIAL_VIEWPORT}
        minZoom={READABLE_MIN_ZOOM}
        maxZoom={READABLE_MAX_ZOOM}
        nodesDraggable
        nodesConnectable
        edgesFocusable
        elementsSelectable
        selectionKeyCode="Shift"
        multiSelectionKeyCode={['Shift', 'Meta', 'Control']}
        selectionMode={SelectionMode.Partial}
        autoPanOnSelection
        deleteKeyCode={['Backspace', 'Delete']}
        proOptions={{ hideAttribution: true }}
      >
        <Background className="dark:opacity-45" color="rgba(14,165,233,0.24)" gap={22} size={1.2} />
        <Controls position="bottom-left" />
        <MiniMap
          position="bottom-right"
          pannable
          zoomable
          bgColor="#ffffff"
          maskColor="rgba(248, 250, 252, 0.72)"
          maskStrokeColor="#cbd5e1"
          nodeColor={(node) => {
            const type = (node.data as ArchitectureGraphNodeData).type;
            if (type === 'kit') return '#fb923c';
            if (type === 'location') return '#34d399';
            if (type === 'zone') return '#818cf8';
            if (type === 'sensor') return '#60a5fa';
            if (type === 'camera') return '#a78bfa';
            if (type === 'threshold') return '#fb7185';
            return '#38bdf8';
          }}
        />
        <button
          type="button"
          onClick={fitReadableView}
          className="absolute bottom-5 left-16 z-10 inline-flex h-9 items-center gap-2 rounded-xl border border-border bg-card/94 px-3 text-xs font-bold text-foreground shadow-sm backdrop-blur transition-colors hover:bg-muted"
          title="Recentrar arquitetura"
        >
          <Maximize2 className="h-3.5 w-3.5 text-primary" />
          <span className="hidden sm:inline">Recentrar</span>
        </button>
        <div className={`absolute left-1/2 top-4 z-10 flex -translate-x-1/2 items-center gap-2 rounded-2xl border border-border bg-card/92 px-3 py-2 shadow-lg backdrop-blur transition-all duration-300 ease-out ${
          toolbarHidden
            ? 'pointer-events-none -translate-y-3 scale-95 opacity-0'
            : 'translate-y-0 scale-100 opacity-100'
        }`}>
          {visiblePaletteNodeTypes.map((item) => {
            const Icon = nodeIconMap[item.type];
            return (
              <button
                key={item.type}
                type="button"
                draggable
                onDragStart={(event) => handlePaletteDragStart(event, item.type)}
                className="flex min-w-[58px] flex-col items-center gap-1 rounded-xl px-2 py-1.5 text-xs font-bold text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
                title={`Arrastar ${item.label}`}
              >
                <span className={`flex h-9 w-9 items-center justify-center rounded-xl border shadow-sm dark:shadow-black/20 ${nodeToneClass[item.type]}`}>
                  <Icon className="h-4 w-4" />
                </span>
                <span className="hidden sm:block">{item.label}</span>
              </button>
            );
          })}
        </div>
        {nodes.length === 0 ? (
          <div className="pointer-events-none absolute inset-0 z-0 flex items-center justify-center">
            <div className="max-w-sm rounded-2xl border border-dashed border-border bg-card/82 px-5 py-4 text-center shadow-sm backdrop-blur">
              <p className="text-sm font-bold text-foreground">Canvas vazio</p>
              <p className="mt-1 text-sm text-muted-foreground">
                Arrasta objetos da barra superior para começar a montar a configuração visual.
              </p>
            </div>
          </div>
        ) : null}
        {selectedEdgeId ? (
          <button
            type="button"
            onClick={removeSelectedEdge}
            className="absolute right-5 top-5 z-10 rounded-xl border border-border bg-card px-3 py-2 text-xs font-bold text-foreground shadow-sm transition-colors hover:bg-muted"
          >
            Remover ligação
          </button>
        ) : null}
      </ReactFlow>
    </div>
  );
}
