import { useCallback, useEffect, useMemo, useState } from 'react';
import { useLanguage } from '@/app/utils/i18n';
import { useAqlOperationalContext } from './AqlOperationalContextProvider';
import {
  sendAqlAssistantQuestion,
  type AqlAssistantCard,
  type AqlAssistantContext,
  type AqlAssistantEvidence,
  type AqlAssistantResponse,
  type AqlAssistantUsage
} from './assistantApi';

export interface AqlAssistantLocalSummary {
  activeAlerts?: number;
  activeCriticalAlerts?: number;
  sensorOutOfRangeCount?: number;
  staleSensorCount?: number;
  deviceOfflineCount?: number;
  growthWarningLevel?: 'none' | 'normal' | 'warning' | 'critical' | null;
  lowMeasurementConfidence?: boolean;
  recentPathologyCases?: number;
}

export interface AqlAssistantMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  createdAt: string;
  cards?: AqlAssistantCard[];
  evidence?: AqlAssistantEvidence[];
}

export interface AqlAssistantTokenBudget {
  provider: string;
  model: string;
  used: number;
  budget: number;
  lastRequest: number;
}

const DEFAULT_TOKEN_BUDGET = 1_000_000;

