  const normalized = sensorType.toLowerCase();
  if (normalized.includes('temperature')) return 'border-orange-500/25 bg-orange-500/10 text-orange-700 dark:text-orange-300';
  if (normalized.includes('ph')) return 'border-sky-500/25 bg-sky-500/10 text-sky-700 dark:text-sky-300';
