const formatCount = (count: number, singular: string, plural: string) => `${count} ${count === 1 ? singular : plural}`;

const slugify = (value: string) =>
  value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '');
const normalizeCameraCode = (value: unknown) => slugify(String(value ?? '')).slice(0, 80);
const liveFeedPathForCameraCode = (code: unknown) => {
  const normalizedCode = normalizeCameraCode(code);
  return normalizedCode ? `live/${normalizedCode}/feed.jpg` : '';
};
const trainingBurstPathForCameraCode = (code: unknown) => {
  const normalizedCode = normalizeCameraCode(code);
  return normalizedCode ? `live/${normalizedCode}/training` : '';
};
const clampTrainingTarget = (value: unknown) => {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return 50;
  return Math.max(1, Math.min(500, Math.floor(parsed)));
};
const slugSegments = (value: unknown) =>
  String(value ?? '')
    .split(/[/?#]+/)
    .map((segment) => slugify(segment))
    .filter(Boolean);
const toId = (value: unknown) => String(value ?? '').trim();
const toQueryPart = (value: unknown) =>
  String(value ?? '')
    .replace(/\s*\/\s*/g, ', ')
    .replace(/\s+/g, ' ')
    .trim();
