const projectMatchesPath = (project: AqlProject, pathSlug: string) => {
  const normalizedPath = slugify(pathSlug);
  const slugParts = slugSegments(project.slug);
  return (
    slugify(project.slug) === normalizedPath ||
    slugParts[slugParts.length - 1] === normalizedPath ||
    slugify(project.name) === normalizedPath
  );
};

