  const handleSave = <K extends keyof AqlConfigurationDataset>(key: K, idKey: string) =>
    async (item: AqlConfigurationDataset[K][number], mode: 'create' | 'edit') => {
      const saved = await saveConfigurationRecord(key, normalizeRecordForSave(key, item));
      setDataset((prev) => {
        const list = [...prev[key]] as Array<Record<string, any>>;
        if (mode === 'create') {
          list.unshift(saved as Record<string, any>);
        } else {
          const index = list.findIndex((entry) => entry[idKey] === (saved as Record<string, any>)[idKey]);
          if (index >= 0) list[index] = saved as Record<string, any>;
          else list.unshift(saved as Record<string, any>);
        }
        return { ...prev, [key]: list } as AqlConfigurationDataset;
      });
    };

