  const handleDelete = <K extends keyof AqlConfigurationDataset>(key: K, idKey: string) =>
    async (item: AqlConfigurationDataset[K][number]) => {
      if (key === 'clients') {
        const clientToDelete = item as AqlClient;
        await deleteClientCascade(clientToDelete);
        setDataset((prev) => {
          const clientId = clientToDelete.client_id;
          const projectIds = new Set(prev.projects.filter((entry) => entry.client_id === clientId).map((entry) => entry.project_id));
          const locationIds = new Set(prev.locations.filter((entry) => entry.client_id === clientId || projectIds.has(entry.project_id)).map((entry) => entry.location_id));
          const zoneIds = new Set(prev.zones.filter((entry) =>
            entry.client_id === clientId ||
            projectIds.has(entry.project_id) ||
            locationIds.has(entry.location_id)
          ).map((entry) => entry.zone_id));
          const kitIds = new Set(prev.kits.filter((entry) =>
            entry.client_id === clientId ||
            projectIds.has(entry.project_id) ||
            locationIds.has(entry.location_id) ||
            (entry.zone_id ? zoneIds.has(entry.zone_id) : false)
          ).map((entry) => entry.kit_id));

          return {
            ...prev,
            clients: prev.clients.filter((entry) => entry.client_id !== clientId),
            projects: prev.projects.filter((entry) => entry.client_id !== clientId),
            locations: prev.locations.filter((entry) => entry.client_id !== clientId && !locationIds.has(entry.location_id)),
            zones: prev.zones.filter((entry) => entry.client_id !== clientId && !zoneIds.has(entry.zone_id)),
            kits: prev.kits.filter((entry) => entry.client_id !== clientId && !kitIds.has(entry.kit_id)),
            cameras: prev.cameras.filter((entry) =>
              !(entry.kit_id && kitIds.has(entry.kit_id)) &&
              !(entry.zone_id && zoneIds.has(entry.zone_id))
            ),
            ultrasoundDevices: prev.ultrasoundDevices.filter((entry) => entry.client_id !== clientId && !kitIds.has(entry.kit_id)),
            sensors: prev.sensors.filter((entry) =>
              !kitIds.has(entry.kit_id) &&
              !(entry.zone_id && zoneIds.has(entry.zone_id))
            ),
            species: prev.species.filter((entry) => entry.client_id !== clientId),
            phases: prev.phases.filter((entry) => entry.client_id !== clientId),
            projectSettings: prev.projectSettings.filter((entry) => entry.client_id !== clientId),
            users: prev.users.filter((entry) => entry.client_id !== clientId)
          };
        });
        toast.success(`Cliente "${clientToDelete.name}" apagado com dados relacionados.`);
        return;
      }

      if (key === 'projects') {
        const projectToDelete = item as AqlProject;
        await deleteProjectCascade(projectToDelete);
        setDataset((prev) => {
          const projectId = projectToDelete.project_id;
          const locationIds = new Set(prev.locations.filter((entry) => entry.project_id === projectId).map((entry) => entry.location_id));
          const zoneIds = new Set(prev.zones.filter((entry) => entry.project_id === projectId || locationIds.has(entry.location_id)).map((entry) => entry.zone_id));
          const kitIds = new Set(prev.kits.filter((entry) =>
            entry.project_id === projectId ||
            locationIds.has(entry.location_id) ||
            (entry.zone_id ? zoneIds.has(entry.zone_id) : false)
          ).map((entry) => entry.kit_id));

          return {
            ...prev,
            projects: prev.projects.filter((entry) => entry.project_id !== projectId),
            locations: prev.locations.filter((entry) => entry.project_id !== projectId && !locationIds.has(entry.location_id)),
            zones: prev.zones.filter((entry) => entry.project_id !== projectId && !zoneIds.has(entry.zone_id)),
            kits: prev.kits.filter((entry) => entry.project_id !== projectId && !kitIds.has(entry.kit_id)),
            cameras: prev.cameras.filter((entry) =>
              !(entry.kit_id && kitIds.has(entry.kit_id)) &&
              !(entry.zone_id && zoneIds.has(entry.zone_id))
            ),
            ultrasoundDevices: prev.ultrasoundDevices.filter((entry) => !kitIds.has(entry.kit_id)),
            sensors: prev.sensors.filter((entry) =>
              !kitIds.has(entry.kit_id) &&
              !(entry.zone_id && zoneIds.has(entry.zone_id))
            ),
            species: prev.species.filter((entry) => entry.project_id !== projectId),
            phases: prev.phases.filter((entry) => entry.project_id !== projectId),
            projectSettings: prev.projectSettings.filter((entry) => entry.project_id !== projectId),
            users: prev.users.filter((entry) => entry.project_id !== projectId)
          };
        });
        toast.success(`Projeto "${projectToDelete.name}" apagado com dados relacionados.`);
        return;
      }

      if (key === 'locations') {
        await deleteLocationCascade(item as AqlLocation);
        await refreshDatasetFromServer();
        toast.success('Instalação apagada com dados relacionados.');
        return;
      }

      if (key === 'zones') {
        await deleteZoneCascade(item as AqlZone);
        await refreshDatasetFromServer();
        toast.success('Área operacional apagada com dados relacionados.');
        return;
      }

      if (key === 'kits') {
        await deleteKitCascade(item as AqlKit);
        await refreshDatasetFromServer();
        toast.success('Edge apagado com feeds e dados relacionados.');
        return;
      }

      if (key === 'cameras') {
        await deleteCameraCascade(item as AqlCamera);
        await refreshDatasetFromServer();
        toast.success('Câmara apagada com dados relacionados.');
        return;
      }

      if (key === 'sensors') {
        await deleteSensorCascade(item as AqlSensor);
        await refreshDatasetFromServer();
        toast.success('Sensor apagado com dados relacionados.');
        return;
      }

      if (key === 'ultrasoundDevices') {
        await deleteUltrasoundDeviceCascade(item as AqlUltrasoundDevice);
        await refreshDatasetFromServer();
        toast.success('Sonda apagada com dados relacionados.');
        return;
      }

      await deleteConfigurationRecord(key, item);
      setDataset((prev) => {
        const list = (prev[key] as Array<Record<string, any>>).filter((entry) => entry[idKey] !== (item as Record<string, any>)[idKey]);
        return { ...prev, [key]: list } as AqlConfigurationDataset;
      });
      toast.success('Registo apagado.');
    };

  const handleUserSave = async (item: AqlUserAccess, mode: 'create' | 'edit') => {
    if (!portalAccess?.accessToken) {
      throw new Error('Portal session is missing the Supabase access token. Please sign in again.');
    }

    const selectedClientIds = isClientMode
      ? [client?.client_id ?? item.client_id].filter(Boolean).map(String)
      : Array.from(new Set([
          ...((item.client_ids ?? []).map(String).filter(Boolean)),
          ...(item.client_id ? [item.client_id] : [])
        ]));
    const scopeClientId = selectedClientIds[0] ?? item.client_id;
    const isProfileSelfEdit = isClientMode && matchesPortalUser(item, portalAccess);
    const lockedProjectIds = isClientMode
      ? Array.from(new Set([
          ...((item.project_ids ?? []).map(String).filter(Boolean)),
          ...(item.project_id ? [item.project_id] : []),
          ...(resolvedProjectSlug && project?.project_id ? [project.project_id] : [])
        ]))
      : null;
    const projectIds = lockedProjectIds ?? (item.project_scope === 'all'
      ? []
      : Array.from(new Set((item.project_ids ?? []).map(String).filter(Boolean))));
    const saved = await saveConfigurationUserAccess({
      ...item,
      client_id: scopeClientId,
      client_ids: selectedClientIds,
      project_ids: projectIds,
      project_id: projectIds[0] ?? null,
      project_scope: projectIds.length ? 'specific' : 'all',
      role: isProfileSelfEdit ? item.role : item.role,
      is_active: isProfileSelfEdit ? item.is_active : item.is_active
    }, mode, portalAccess);
    setDataset((prev) => {
      const list = [...prev.users];
      if (mode === 'create') {
        list.unshift(saved);
      } else {
        const index = list.findIndex((entry) => entry.user_id === saved.user_id);
        if (index >= 0) list[index] = saved;
        else list.unshift(saved);
      }
      return { ...prev, users: list };
    });
  };

