// ─── Helpers ────────────────────────────────────────────────────────────────

const handleQueryError = <T,>(result: { data: unknown; error: unknown }, context: string): T => {
  if (result.error) {
    const message = result.error instanceof Error ? result.error.message : String(result.error);
    throw new Error(`${context}: ${message}`);
  }
  return (result.data ?? []) as unknown as T;
};

const applyOptionalEq = <Q extends { eq: (column: string, value: string) => Q }>(
  query: Q,
  column: string,
  value: string | undefined
): Q => (value ? query.eq(column, value) : query);

const toIsoDate = (date: Date): string => date.toISOString().slice(0, 10);

export const isoDaysAgo = (days: number): string => {
  const date = new Date();
  date.setUTCHours(0, 0, 0, 0);
  date.setUTCDate(date.getUTCDate() - days);
  return toIsoDate(date);
};

export const todayIso = (): string => {
  const date = new Date();
  date.setUTCHours(0, 0, 0, 0);
  return toIsoDate(date);
};

// ─── Filter sources ─────────────────────────────────────────────────────────

export async function fetchClients(): Promise<AqlOption[]> {
  const result = await supabase
    .from('aql_clients')
    .select('id:client_id, name')
    .order('name', { ascending: true });
  return handleQueryError(result, 'Failed to load clients') as AqlOption[];
}

export async function fetchProjects(clientId?: string): Promise<AqlOption[]> {
  let query = supabase.from('aql_projects').select('id:project_id, name').order('name', { ascending: true });
  query = applyOptionalEq(query, 'client_id', clientId);
  return handleQueryError(await query, 'Failed to load projects') as AqlOption[];
}

