// ─── Dashboard series (main time-series — aggregated) ───────────────────────

export async function fetchDashboardSeries(filters: GrowthFilters): Promise<AqlGrowthDashboardPoint[]> {
  const selectColumns = [
    'cohort_id',
    'zone_id',
    'period_start',
    'period_end',
    'median_size',
    'avg_size',
    'p10_size',
    'p25_size',
    'p75_size',
    'p90_size',
    'sample_count',
    'rejected_count',
    'confidence',
    'uniformity_score',
    'warning_level',
    'has_enough_sample'
  ].join(', ');

  const runQuery = async (includeScopeFilters: boolean) => {
    let query = supabase
      .from('aql_growth_dashboard_series')
      .select(selectColumns)
      .gte('period_start', filters.fromDate)
      .lte('period_start', filters.toDate)
      .order('period_start', { ascending: true });

    if (includeScopeFilters) {
      query = applyOptionalEq(query, 'client_id', filters.clientId);
      query = applyOptionalEq(query, 'project_id', filters.projectId);
      query = applyOptionalEq(query, 'location_id', filters.locationId);
      query = applyOptionalEq(query, 'species_id', filters.speciesId);
      query = applyOptionalEq(query, 'phase_id', filters.phaseId);
    }

    query = applyOptionalEq(query, 'cohort_id', filters.cohortId);
    query = applyOptionalEq(query, 'zone_id', filters.zoneId);

    return query;
  };

  let result = await runQuery(true);
  const hasScopeFilters = Boolean(filters.clientId || filters.projectId || filters.locationId || filters.speciesId || filters.phaseId);
  const errorMessage = result.error instanceof Error ? result.error.message : String(result.error ?? '');
  if (hasScopeFilters && result.error && /schema cache|column .* does not exist|could not find/i.test(errorMessage)) {
    result = await runQuery(false);
  }

  return handleQueryError(result, 'Failed to load growth series') as AqlGrowthDashboardPoint[];
}

// ─── Raw measurements (latest distribution + table) ─────────────────────────

export async function fetchLatestDayMeasurements(filters: {
  cohortId?: string;
  zoneId?: string;
  /** ISO date (yyyy-mm-dd). When omitted, returns the latest day with data. */
  day?: string;
  limit?: number;
}): Promise<AqlGrowthMeasurement[]> {
  if (!filters.cohortId && !filters.zoneId) return [];

  const dayStart = filters.day ? `${filters.day}T00:00:00.000Z` : undefined;
  const dayEnd = filters.day ? `${filters.day}T23:59:59.999Z` : undefined;

  let query = supabase
    .from('aql_growth_measurements')
    .select(
      [
        'id',
        'cohort_id',
        'zone_id',
        'camera_id',
        'capture_id',
        'detection_id',
        'measured_at',
        'length_mm',
        'width_mm',
        'area_mm2',
        'estimated_weight_g',
        'detection_confidence',
        'measurement_quality',
        'is_valid',
        'rejection_reason'
      ].join(', ')
    )
    .order('measured_at', { ascending: false })
    .limit(filters.limit ?? 1000);

  query = applyOptionalEq(query, 'cohort_id', filters.cohortId);
  query = applyOptionalEq(query, 'zone_id', filters.zoneId);
  if (dayStart) query = query.gte('measured_at', dayStart);
  if (dayEnd) query = query.lte('measured_at', dayEnd);

  return handleQueryError(await query, 'Failed to load measurements') as AqlGrowthMeasurement[];
}

