// ─── Calibration ────────────────────────────────────────────────────────────

export async function fetchActiveCalibration(filters: {
  zoneId?: string;
  cameraId?: string;
}): Promise<AqlGrowthCalibration | null> {
  if (!filters.zoneId && !filters.cameraId) return null;

  let query = supabase
    .from('aql_growth_calibrations')
    .select(
      [
        'id',
        'zone_id',
        'camera_id',
        'pixel_to_mm_ratio',
        'calibration_type',
        'position_code',
        'qr_code',
        'quality_score',
        'valid_from',
        'valid_to',
        'is_active'
      ].join(', ')
    )
    .eq('is_active', true)
    .order('valid_from', { ascending: false })
    .limit(1);

  query = applyOptionalEq(query, 'zone_id', filters.zoneId);
  query = applyOptionalEq(query, 'camera_id', filters.cameraId);

  const result = await query;
  if (result.error) throw new Error(`Failed to load calibration: ${result.error.message ?? result.error}`);
  const rows = (result.data ?? []) as unknown as AqlGrowthCalibration[];
  return rows[0] ?? null;
}

// ─── Captures ───────────────────────────────────────────────────────────────

export async function fetchRecentCaptures(filters: {
  zoneId?: string;
  cohortId?: string;
  limit?: number;
}): Promise<AqlVisionCapture[]> {
  if (!filters.zoneId && !filters.cohortId) return [];

  let query = supabase
    .from('aql_vision_captures')
    .select('id, zone_id, cohort_id, image_url, captured_at, sample_count, median_size')
    .order('captured_at', { ascending: false })
    .limit(filters.limit ?? 8);

  query = applyOptionalEq(query, 'zone_id', filters.zoneId);
  query = applyOptionalEq(query, 'cohort_id', filters.cohortId);

  return handleQueryError(await query, 'Failed to load captures') as AqlVisionCapture[];
}

// ─── RPC: refresh aggregated metrics for one day ────────────────────────────

export async function refreshGrowthMetricDay(params: {
  cohortId?: string;
  zoneId?: string;
  /** ISO date string (yyyy-mm-dd). Defaults to today. */
  day?: string;
}): Promise<void> {
  const payload: Record<string, string> = {
    p_day: params.day ?? todayIso()
  };
  if (params.cohortId) payload.p_cohort_id = params.cohortId;
  if (params.zoneId) payload.p_zone_id = params.zoneId;

  const result = await supabase.rpc('aql_refresh_growth_metric_day', payload);
  if (result.error) {
    throw new Error(`Failed to refresh growth metrics: ${result.error.message ?? result.error}`);
  }
}
